const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export async function mountReviews(panel,rule){const [r,m]=await Promise.all([fetch('/api/product-reviews?product='+encodeURIComponent(rule.id)),fetch('/api/customer/me')]);const data=await r.json(),me=await m.json();if(!panel.isConnected)return;panel.innerHTML=`<h3>Customer reviews</h3><div data-review-list>${(data.reviews||[]).map(x=>`<article><b>${'★'.repeat(x.rating)}${'☆'.repeat(5-x.rating)}</b><p>${esc(x.body)}</p><small>${esc(x.name)} · ${esc(x.created_at.slice(0,10))}</small></article>`).join('')||'<p>No customer reviews for this product yet.</p>'}</div><details><summary>Preview examples · sample content</summary>${['Clear artwork and a professional finish.','The options make it easy to configure a print order.','A consistent look for our brand.'].map(t=>`<article class="sample-review"><b>★★★★★ · Demonstration only</b><p>${t}</p><small>Sample text · not a customer testimonial</small></article>`).join('')}</details>${me.customer?'<form class="batch-review-form"><label>Your rating<select name="rating">'+[5,4,3,2,1].map(n=>`<option value="${n}">${n} stars</option>`).join('')+'</select></label><label>Your review<textarea name="body" required minlength="10" maxlength="1500"></textarea></label><button class="btn">Publish review</button><p role="status" data-review-status></p></form>':`<p><a class="btn ghost" href="/signin-with-chatgpt?return_to=${encodeURIComponent(rule.path+'/')}">Log in to write a review</a></p>`}`;panel.querySelector('form')?.addEventListener('submit',async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const values=Object.fromEntries(new FormData(e.target)),r=await fetch('/api/product-reviews',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({product:rule.id,rating:Number(values.rating),body:values.body})}),v=await r.json();if(!r.ok)throw Error(v.error);await mountReviews(panel,rule);}catch(err){panel.querySelector('[data-review-status]').textContent=err.message;b.disabled=false;}});}
